import React from 'react';
import { useNavigate } from 'react-router-dom';

const templates = [
  { key: 'classic', name: 'Classic', description: 'Professional and traditional layout' },
  { key: 'modern', name: 'Modern', description: 'Clean and contemporary design' },
  { key: 'minimal', name: 'Minimal', description: 'Simple and elegant style' },
  { key: 'creative', name: 'Creative', description: 'Unique and eye-catching design' },
];

function TemplateGallery() {
  const navigate = useNavigate();
  const handleSelect = (key) => {
    localStorage.setItem('selectedTemplate', key);
    navigate('/builder');
  };
  return (
    <div className="template-gallery">
      <h2>Choose Your Resume Template</h2>
      <div className="template-gallery-list">
        {templates.map(t => (
          <div className="template-card" key={t.key} onClick={() => handleSelect(t.key)}>
            <div className="template-img">
              <div className="template-preview">
                <h3>{t.name}</h3>
                <p>{t.description}</p>
              </div>
            </div>
            <div className="template-name">{t.name}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default TemplateGallery;
